import pandas as pd
import numpy as np

SPECIES_MAP = {'adelie': 'Adelie', 'chinstrap': 'Chinstrap', 'chinstarp': 'Chinstrap', 'gentoo': 'Gentoo'}

def clean(df):
    d = df.copy()
    # normalize text columns
    for c in ['penguin_id', 'species', 'island', 'sex']:
        if c in d.columns:
            d[c] = d[c].astype('object').where(d[c].notna(), np.nan)
            d[c] = d[c].apply(lambda v: v.strip() if isinstance(v, str) else v)
    # fix species label variants (case/whitespace/typo)
    if 'species' in d.columns:
        d['species'] = d['species'].apply(
            lambda v: SPECIES_MAP.get(str(v).strip().lower(), v) if pd.notna(v) else np.nan)
    # coerce numeric text to numbers
    for c in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if c in d.columns:
            d[c] = pd.to_numeric(d[c], errors='coerce')
    # fix sign errors in flipper length (lengths cannot be negative)
    if 'flipper_length_mm' in d.columns:
        d['flipper_length_mm'] = d['flipper_length_mm'].abs()
        d.loc[~d['flipper_length_mm'].between(170, 235), 'flipper_length_mm'] = np.nan
    # out-of-range body mass -> missing (do not guess)
    if 'body_mass_g' in d.columns:
        d.loc[~d['body_mass_g'].between(2500, 6500), 'body_mass_g'] = np.nan
    if 'bill_length_mm' in d.columns:
        d.loc[~d['bill_length_mm'].between(30, 60), 'bill_length_mm'] = np.nan
    # drop exact duplicate rows
    d = d.drop_duplicates()
    return d.reset_index(drop=True)

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['island'])
    counts = d.groupby('island')['penguin_id'].nunique()
    return {str(k): int(v) for k, v in counts.items()}
